from fractions import Fraction as Fr
M=Fr(3); rho=Fr(1,2)
b=[Fr(2),Fr(5)]
def S(n): return sum(((n-k+1)*b[n-k+1]+b[n-k])*rho**(-k) for k in range(n+1))
for n in range(40): b.append(M*S(n)/((n+2)*(n+1)))
for n in range(1,39):
    assert S(n)==(n+1)*b[n+1]+b[n]+S(n-1)/rho
    assert M*S(n-1)==(n+1)*n*b[n+1]
    assert M*b[n]/b[n+1]<=n+1
assert abs(float(b[41]/b[40])-2.0)<0.2

import sympy as sp
x=sp.symbols('x',positive=True); r=sp.symbols('r')
assert set(sp.solve(r*(r-1)+r/2,r))=={0,sp.Rational(1,2)}
for y in [sp.cos(sp.sqrt(2*x)),sp.sin(sp.sqrt(2*x))/sp.sqrt(2)]:
    assert sp.simplify(2*x*sp.diff(y,x,2)+sp.diff(y,x)+y)==0
s1=sum((-1)**n*(2*x)**n/sp.factorial(2*n) for n in range(8))
s2=sp.sqrt(x)*sum((-1)**n*(2*x)**n/sp.factorial(2*n+1) for n in range(8))
for X in [sp.Rational(1,3),sp.Rational(3,2)]:
    assert abs(sp.N(s1.subs(x,X)-sp.cos(sp.sqrt(2*X))))<1e-9
    assert abs(sp.N(s2.subs(x,X)-sp.sin(sp.sqrt(2*X))/sp.sqrt(2)))<1e-9
